SELECT
    UZDT.KURIKOSHIKIN
FROM
    S07T002T UZDT
WHERE
    UZDT.APKIHONCD = #{apkihoncd,jdbcType=VARCHAR}
    AND UZDT.SHOPCD = #{shopcd,jdbcType=VARCHAR}
    AND UZDT.TOKUISAKICD = #{tokuisakicd,jdbcType=VARCHAR}
    AND TO_DATE(UZDT.SHIMEDYDM || UZDT.SHIMEDD, 'YYYYMMDD') = (
        SELECT
            MAX(TO_DATE(SHIMEDYDM || SHIMEDD, 'YYYYMMDD'))
        FROM
            S07T002T
        WHERE
            APKIHONCD = #{apkihoncd,jdbcType=VARCHAR}
            AND SHOPCD = #{shopcd,jdbcType=VARCHAR}
            AND TOKUISAKICD = #{tokuisakicd,jdbcType=VARCHAR}
            AND YUKOKBN = '1'
    )
AND UZDT.YUKOKBN = '1'

